from collections import defaultdict
expenses=[]
def add_expense(amount,category):
    if amount<=0: raise ValueError('금액 확인')
    expenses.append({'amount':amount,'category':category or '기타'})
def totals(items):
    result=defaultdict(int)
    for x in items: result[x['category']]+=x['amount']
    return dict(result)
add_expense(12000,'식비')
print(totals(expenses))

import java.time.LocalDateTime;
import java.util.*;
class Booking { LocalDateTime start,end; boolean cancelled; Booking(LocalDateTime s,LocalDateTime e){if(!s.isBefore(e))throw new IllegalArgumentException();start=s;end=e;} }
class BookingManager { List<Booking> items=new ArrayList<>(); boolean add(Booking b){boolean conflict=items.stream().anyMatch(x->!x.cancelled&&b.start.isBefore(x.end)&&b.end.isAfter(x.start));if(conflict)return false;items.add(b);return true;} }

type Product={id:number;title:string;price:number;seller:string};
const products:Product[]=[];const favorites=new Set<number>();
function add(title:string,price:number,seller:string){if(!title.trim()||price<0||!seller.trim())throw Error('입력 확인');const p={id:Date.now(),title,price,seller};products.push(p);return p}
function search(q:string){return products.filter(p=>p.title.toLowerCase().includes(q.toLowerCase()))}
